using System;using System.Data.SqlClient;
namespace Training.Manager{public partial class TrainingCalendar:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private DateTime Month{get{return ViewState["Month"]==null?new DateTime(DateTime.Now.Year,DateTime.Now.Month,1):(DateTime)ViewState["Month"]; }set{ViewState["Month"]=value;}}private string MID{get{return Session["ManagerID"]==null?"":Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(string.IsNullOrWhiteSpace(MID))Response.Redirect("~/Default.aspx");if(!IsPostBack){Month=new DateTime(DateTime.Now.Year,DateTime.Now.Month,1);BindGrid();}}private void BindGrid(){lblMonth.Text=Month.ToString("MMMM yyyy");string q="SELECT SM.SessionDate,SM.TrainingID,TD.Batch,SM.SessionNo,SM.SessionName,ISNULL(EBM.EmpName,TME.NameExternal) TrainerName,ISNULL(SM.AttendanceStatus,'Pending') AttendanceStatus FROM SessionMaster SM INNER JOIN TrainingDetails TD ON SM.TrainingID=TD.TrainingID INNER JOIN TrainingLocationMaster L ON TD.TrainingLocation=L.TrainingLocation INNER JOIN ManagerMaster M ON M.TrainingLocationID=L.TrainingLocationID LEFT JOIN EmpBasicMaster EBM ON SM.TrainerID=EBM.EmpID LEFT JOIN TrainerMaster TME ON SM.TrainerID=TME.TrainerID WHERE M.ManagerID=@ManagerID AND ISNULL(M.ActiveStatus,'Y')='Y' AND TRY_CONVERT(date,SM.SessionDate,105)>=@StartDate AND TRY_CONVERT(date,SM.SessionDate,105)<@EndDate ORDER BY TRY_CONVERT(date,SM.SessionDate,105),TRY_CONVERT(int,SM.SessionNo)";gvCalendar.DataSource=obj.GetDataTable(q,new SqlParameter[]{new SqlParameter("@ManagerID",MID),new SqlParameter("@StartDate",Month),new SqlParameter("@EndDate",Month.AddMonths(1))});gvCalendar.DataBind();}protected void btnPrev_Click(object s,EventArgs e){Month=Month.AddMonths(-1);BindGrid();}protected void btnNext_Click(object s,EventArgs e){Month=Month.AddMonths(1);BindGrid();}protected void btnToday_Click(object s,EventArgs e){Month=new DateTime(DateTime.Now.Year,DateTime.Now.Month,1);BindGrid();}}}